package com.inventra.backend.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDateTime; import java.util.*;
@Document(collection="orders") public class Order { @Id private String id; private String orderNumber; private String warehouseId; private String customerName; private List<OrderItem> items=new ArrayList<>(); private OrderStatus status=OrderStatus.CREATED; private double totalAmount; private LocalDateTime createdAt=LocalDateTime.now(); private LocalDateTime updatedAt=LocalDateTime.now(); public Order(){} public String getId(){return id;} public void setId(String v){id=v;} public String getOrderNumber(){return orderNumber;} public void setOrderNumber(String v){orderNumber=v;} public String getWarehouseId(){return warehouseId;} public void setWarehouseId(String v){warehouseId=v;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public List<OrderItem> getItems(){return items;} public void setItems(List<OrderItem> v){items=v;} public OrderStatus getStatus(){return status;} public void setStatus(OrderStatus v){status=v;} public double getTotalAmount(){return totalAmount;} public void setTotalAmount(double v){totalAmount=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;} }
